import numpy as np

def _arrays(rewards, behavior_probs, target_probs):
    r = np.asarray(rewards, dtype=float)
    p = np.asarray(behavior_probs, dtype=float)
    q = np.asarray(target_probs, dtype=float)
    if r.ndim != 1 or p.shape != r.shape or q.shape != r.shape or r.size == 0:
        raise ValueError("equal non-empty vectors required")
    if np.any(p <= 0) or np.any(p > 1) or np.any((q < 0) | (q > 1)):
        raise ValueError("invalid probabilities")
    return r, p, q

def ips_value(rewards, behavior_probs, target_probs):
    r, p, q = _arrays(rewards, behavior_probs, target_probs)
    return float(np.mean(q * r / p))

def snips_value(rewards, behavior_probs, target_probs):
    r, p, q = _arrays(rewards, behavior_probs, target_probs)
    w = q / p
    if w.sum() <= 0:
        raise ValueError("zero total target weight")
    return float(np.dot(w, r) / w.sum())

def doubly_robust_value(
    rewards,
    behavior_probs,
    target_probs,
    predictions_logged,
    predictions_target,
):
    r, p, q = _arrays(rewards, behavior_probs, target_probs)
    logged = np.asarray(predictions_logged, dtype=float)
    target = np.asarray(predictions_target, dtype=float)
    if logged.shape != r.shape or target.shape != r.shape:
        raise ValueError("prediction shapes must match")
    return float(np.mean(target + q / p * (r - logged)))
```

Если $\pi(a\mid x)=0.5$, то при $\mu=0.5$ вес равен 1, а при $\mu=0.01$ — уже 50. Одно наблюдение с таким весом способно доминировать в оценке; это и есть практическая цена слабого перекрытия.

