from math import comb
import numpy as np

def stable_softmax(logits, temperature=1.0):
    z = np.asarray(logits, dtype=float)
    if z.ndim != 1 or z.size == 0 or not np.all(np.isfinite(z)):
        raise ValueError("invalid logits")
    if temperature <= 0 or not np.isfinite(temperature):
        raise ValueError("temperature must be positive")
    scaled = z / temperature
    weights = np.exp(scaled - scaled.max())
    return weights / weights.sum()

def categorical_entropy(probabilities):
    p = np.asarray(probabilities, dtype=float)
    if p.ndim != 1 or np.any(p < 0) or not np.isclose(p.sum(), 1):
        raise ValueError("invalid probability vector")
    positive = p[p > 0]
    return float(-np.dot(positive, np.log(positive)))

def best_of_n_success(p, n):
    if not 0 <= p <= 1 or n < 1:
        raise ValueError("invalid p or n")
    if p == 1:
        return 1.0
    return float(-np.expm1(n * np.log1p(-p)))

def pass_at_k(n, c, k):
    if n <= 0 or c < 0 or c > n or k <= 0 or k > n:
        raise ValueError("invalid n, c, k")
    if n - c < k:
        return 1.0
    return float(1 - comb(n - c, k) / comb(n, k))
```

Проверка энтропии:

```python
logits = np.array([0.0, 1.0, 2.0])
entropies = [
    categorical_entropy(stable_softmax(logits, temperature=t))
    for t in (0.5, 1.0, 2.0)
]
assert entropies[0] < entropies[1] < entropies[2]
```

Это свойство чистого softmax при фиксированных логитах. Оно не утверждает, что более высокая температура улучшает качество, калибровку или истинность ответа.
